x.append(R(6459025,"मसालेदार नींबू-दही चिकन टेंडर्स","चटपटे और स्मोकी स्वाद वाले ये कोमल चिकन बाइट्स गर्मियों में हफ़्ते के किसी भी दिन के रात के खाने के लिए आसान व्यंजन हैं। सुबह चिकन को मैरिनेड में मिला दें और शाम को वह ग्रिल पर डालने के लिए तैयार रहेगा। साथ में ताज़ा ब्रोकली सलाद परोसें।","4","2 टेंडर",
["8 साबुत चिकन टेंडरलॉइन ((लगभग 1 पाउंड))","1 कप सादा नॉनफैट ग्रीक योगर्ट","2 बड़े चम्मच नींबू का रस","1 बड़ा चम्मच नींबू का ज़ेस्ट","1 बड़ा चम्मच पेपरिका","1 बड़ा चम्मच ताज़ा अदरक (कद्दूकस किया हुआ)","1 छोटा चम्मच पिसा जीरा","1/2 छोटा चम्मच लहसुन पाउडर","1/2 छोटा चम्मच नमक","1 मध्यम नींबू (चार टुकड़ों में कटा हुआ, वैकल्पिक, परोसने के लिए)"],
["नींबू के चार टुकड़ों को छोड़कर सभी सामग्री को 1 गैलन के दोबारा बंद होने वाले प्लास्टिक बैग में मिलाएँ। कसकर बंद करें और आगे-पीछे हिलाकर अच्छी तरह लपेट दें। 8 घंटे रेफ्रिजरेटर में रखें।","एक ग्रिल पैन पर भरपूर कुकिंग स्प्रे लगाकर मध्यम-तेज़ आंच पर गरम करें। चिकन को मैरिनेड से निकालें, मैरिनेड फेंक दें, और हर तरफ 3 मिनट या बीच से गुलाबी रंग जाने तक ग्रिल करें। चाहें तो नींबू के टुकड़ों के साथ परोसें।"]))
x.append(R(6459632,"उबला हुआ अंडा","अंडे स्वाभाविक रूप से मधुमेह के अनुकूल भोजन हैं, जो प्रोटीन से भरपूर और कम कार्ब वाले होते हैं। साथ ही, ये हमारे आसान एग सलाद सहित कई अलग-अलग रेसिपी में बेहतरीन सामग्री हैं। ऑनलाइन उबले अंडों की सैकड़ों रेसिपी लगती हैं, लेकिन शेफ जेनिफर लैम्पलॉ की यह रेसिपी हमारी पसंदीदा है क्योंकि यह लगभग हर बार सफल होती है और एक जैसे नतीजे देती है। उनका राज़? जो अंडे आप उबालने वाले हैं, उन्हें उबालने से 10 दिन से 2 हफ़्ते पहले खरीदकर रेफ्रिजरेटर में रखें। पुराने अंडे ताज़े अंडों की तुलना में बेहतर उबलते और छिलते हैं। साथ ही, अगर आप उन्हें ज़्यादा पका दें तो जर्दी के चारों ओर हरे रंग का घेरा बन जाएगा। इससे पहली बार पकाने वाले कई लोग डर जाते हैं, लेकिन चिंता न करें। इसे खाना बिल्कुल ठीक है, इसका मतलब बस इतना है कि अंडा थोड़ा ज़्यादा पक गया है।","6","1 अंडा",
["6 बड़े अंडे","4 कप पानी"],
["अंडों को एक बड़े सॉस पैन की तली में एक परत में रखें और ठंडे पानी से ढक दें ताकि अंडों के ऊपर लगभग एक इंच पानी रहे।","पैन को स्टोव के बर्नर पर रखें, लेकिन आंच चालू करने से पहले 20 मिनट का टाइमर लगा दें।","टाइमर शुरू करें, फिर आंच तेज़ करें और उबाल आने दें। उबाल आने पर आंच कम करके हल्की आंच पर तब तक पकाएँ जब तक टाइमर न बज जाए।","टाइमर बजते ही पैन का पानी तुरंत निथार दें, फिर पैन में अंडों को हल्के से हिलाएँ ताकि छिलके चटक जाएँ।","अंडों को बर्फ़ के पानी में डुबो दें और 15 मिनट तक बर्फ़ के पानी में रहने दें।","बर्फ़ का पानी निथार दें, फिर हर अंडे को पेपर टॉवल पर हल्के से लुढ़काएँ ताकि छिलका ढीला हो जाए, और अंडे का छिलका उतार दें।","एयरटाइट डिब्बे में रेफ्रिजरेटर में एक हफ़्ते तक रखें।"]))
x.append(R(6460004,"बेक किए मसालेदार शकरकंद फ्राइज़ और कम वसा वाले योगर्ट की डिपिंग सॉस के साथ","स्वादिष्ट मसालों वाले ये आपके आम शकरकंद फ्राइज़ नहीं हैं। चटपटी और मलाईदार डिपिंग सॉस के साथ परोसा गया यह साइड डिश ऐसा है जिसे आप साल भर बनाना चाहेंगे।","6","1/2 कप शकरकंद फ्राइज़ + 2 बड़े चम्मच डिपिंग सॉस",
["2 बड़े शकरकंद (छिले हुए और फ्राइज़ के आकार में कटे हुए)","1 बड़ा चम्मच ऑलिव ऑयल","1 छोटा चम्मच स्मोक्ड पेपरिका","1/2 छोटा चम्मच जीरा (साबुत)","1/2 छोटा चम्मच लहसुन पाउडर","1/2 छोटा चम्मच प्याज पाउडर","1/2 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1/2 कप सादा नॉनफैट ग्रीक योगर्ट","1 बड़ा चम्मच नींबू का रस","1 छोटा चम्मच मेपल सिरप","1/2 छोटा चम्मच पिसा जीरा"],
["ओवन को पहले से 425 डिग्री F पर गरम करें और बेकिंग शीट पर बेकिंग पेपर बिछा लें।","एक बड़े कटोरे में शकरकंद फ्राइज़ को ऑलिव ऑयल, स्मोक्ड पेपरिका, जीरा, लहसुन पाउडर, प्याज पाउडर, नमक और काली मिर्च के साथ बराबर लपेटने तक मिलाएँ।","मसाले लगे शकरकंद फ्राइज़ को तैयार बेकिंग शीट पर एक परत में फैलाएँ, ध्यान रखें कि वे ठसाठस न हों।","अतिरिक्त कुरकुरेपन के लिए फ्राइज़ पर हल्का सा कुकिंग स्प्रे करें।","पहले से गरम ओवन में 20–25 मिनट या शकरकंद फ्राइज़ के सुनहरे भूरे और कुरकुरे होने तक बेक करें, बीच में एक बार पलट दें।","डिपिंग सॉस के लिए: एक छोटे कटोरे में कम वसा वाला ग्रीक योगर्ट, नींबू का रस, मेपल सिरप और पिसा जीरा फेंट लें।","डिपिंग सॉस को अलग से परोसें।"]))
x.append(R(6460699,"गर्मियों का मुख्य व्यंजन सलाद","ग्रिल किए सरलॉइन स्टेक, ढेर सारी सब्ज़ियों और लहसुन वाली विनेग्रेट से बने इस भरपेट सलाद को इस गर्मी में अपनी मेज़ का मुख्य आकर्षण बनने दें!\n\nयह रेसिपी और अन्य रेसिपी हमारी कुकबुक, कंप्लीट मंथ ऑफ़ मील्स में पाएँ, जहाँ आप भोजन की योजना आसानी से बनाने के लिए रेसिपी को मिला-जुलाकर इस्तेमाल कर सकते हैं!","4","3 औंस मांस + 1 1/2 बड़े चम्मच ड्रेसिंग + 1 1/3 कप सब्ज़ियाँ + 1 कप हरी पत्तेदार सब्ज़ियाँ",
["1 कप फ्रोज़न मक्का","4 छोटे चम्मच कैनोला तेल","3 कली लहसुन (कटी हुई)","1/4 कप रेड वाइन विनेगर","1 बड़ा चम्मच डिजॉन सरसों","1/4 छोटा चम्मच काली मिर्च (स्वादानुसार)","1/4 छोटा चम्मच चीनी","12 औंस ग्रिल किया हुआ सरलॉइन","1 कप पके आलू (टुकड़ों में कटे हुए)","1 कप हरा प्याज (स्प्रिंग अनियन) (कटा हुआ)","1/2 कप गाजर (पतली कटी हुई)","1 कप लाल शिमला मिर्च (छोटे टुकड़ों में कटी हुई)","1 कप हरी शिमला मिर्च (छोटे टुकड़ों में कटी हुई)","4 कप बेबी सलाद ग्रीन्स"],
["पैकेट पर दिए निर्देशों के अनुसार मक्का पकाएँ।","एक छोटे सॉस पैन में तेल गरम करें; लहसुन डालें और भूरा होने तक भूनें।","आंच से उतारकर ठंडा करें; तेल को छानकर अलग रख लें; लहसुन फेंक दें।","एक बड़े कटोरे में अलग रखा तेल, सिरका, सरसों, काली मिर्च और चीनी मिलाएँ। चाहें तो 1/2 छोटा चम्मच नमक डालें।","तेल के मिश्रण को मक्का, सरलॉइन, आलू, हरे प्याज, गाजर और दोनों तरह की शिमला मिर्च के साथ मिलाएँ। अच्छी तरह मिलाएँ, ढककर ठंडा करें।","सलाद ग्रीन्स बिछाए हुए कटोरे में परोसें।"]))
x.append(R(6460875,"ताज़े बेरीज़ के साथ लेमन शिफॉन","लेखिका बारबरा सीलिग-ब्राउन कहती हैं, \"यह स्वादिष्ट मीठी-खट्टी मिठाई बहुत ताज़गी भरी है और मुँह में घुल जाती है। यह इतनी हल्की है कि इसे बिना अपराध-बोध के खाया जा सकता है। मिठाई में फल शामिल करने से कैलोरी और वसा की मात्रा कम करने में मदद मिलती है। आप इसे पार्टी से एक-दो दिन पहले बना सकते हैं और स्वादों के आपस में घुल जाने के बाद यह और भी बेहतर हो जाएगी।\"","6","1/2 कप",
["1/3 कप नींबू का रस (लगभग 2 बड़े नींबू से)","1/2 कप कम कैलोरी वाला चीनी का विकल्प","4 बड़े अंडे","3 कप ताज़े बेरीज़ (जैसे स्ट्रॉबेरी, ब्लूबेरी और ब्लैकबेरी)"],
["नींबू का रस और चीनी का विकल्प सॉस पैन में डालें। चीनी घुलने तक गरम करें और चलाएँ। आंच से उतार लें।","अंडों को कटोरे में फोड़ें और अच्छी तरह फेंटें। फेंटते हुए नींबू-चीनी का मिश्रण धीरे-धीरे अंडों में डालें। 1 मिनट तक फेंटें, फिर अंडे के मिश्रण को वापस सॉस पैन में डालें।","धीमी से मध्यम आंच पर कई मिनट तक फेंटते हुए पकाएँ जब तक अंडे का मिश्रण गाढ़ा न हो जाए। (जितना ज़्यादा फेंटेंगे, मिश्रण उतना हल्का होगा।) आपके उपकरण के आधार पर इसमें 2-5 मिनट लगेंगे। मिश्रण को आंच से तब उतारें जब वह चम्मच के पिछले हिस्से पर लिपटने लगे।","एक घंटे या उससे अधिक समय के लिए रेफ्रिजरेटर में रखें। ठंडा होने पर यह और गाढ़ा हो जाएगा।","थोड़ा लेमन शिफॉन मिठाई के गिलास या कटोरे में डालें और ऊपर से बेरीज़ डालें। लेमन क्रीम और बेरीज़ की परतें बारी-बारी से लगाएँ। ऊपर से बेरीज़ डालें।"]))
x.append(R(6461142,"चिकन नगेट्स हनी मस्टर्ड डिपिंग सॉस के साथ","यह रेसिपी न सिर्फ़ स्वादिष्ट है, बल्कि गुर्दों के लिए भी अनुकूल है। बारबेक्यू सॉस, करी सॉस, फलों के स्प्रेड या कम सोडियम वाली सलाद ड्रेसिंग जैसी अलग-अलग डिपिंग सॉस आज़माएँ।","12","3 नगेट्स + 1 बड़ा चम्मच सॉस",
["3 कप कॉर्न फ्लेक्स","2 बड़े चम्मच 1% दूध","1 बड़ा अंडा","2 छोटे चम्मच वॉरसेस्टरशायर सॉस","3 बड़े चम्मच शहद","1/2 कप मेयोनेज़","1 बड़ा चम्मच पीली सरसों","1 पाउंड बिना हड्डी और बिना त्वचा के चिकन ब्रेस्ट","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे"],
["सरसों, मेयोनेज़, शहद और वॉरसेस्टरशायर सॉस को एक छोटे कटोरे में मिलाएँ। नगेट्स के पकने तक सॉस को ठंडा करने के लिए रेफ्रिजरेटर में रखें।","ओवन को 400°F पर पहले से गरम करें।","चिकन ब्रेस्ट को 36 निवाले के आकार के टुकड़ों में काटें।","फेंटा हुआ अंडा और दूध एक छोटे कटोरे में मिलाएँ। चिकन के टुकड़ों को अंडे के मिश्रण में डुबोएँ, फिर ज़िप-लॉक बैग में हिलाकर कॉर्नफ्लेक्स के चूरे से लपेटें।","नगेट्स को नॉन-स्टिक कुकिंग स्प्रे लगी बेकिंग शीट पर 15 मिनट तक पकने तक बेक करें।"]))
x.append(R(6461143,"ग्लूटेन-मुक्त बनाना ब्रेड","यह ग्लूटेन-मुक्त बनाना ब्रेड वैलेंटाइन डे के लिए एक अच्छा तोहफ़ा हो सकती है, और यह ग्लूटेन-मुक्त है! एक बड़े लोफ की जगह आप इसे चार मिनी लोफ पैन में बना सकते हैं, जिससे छोटी ब्रेड बनेंगी जिन्हें लपेटकर वैलेंटाइन उपहार के रूप में दिया जा सकता है।","16","1 स्लाइस",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","4 मध्यम केले (बहुत पके, मसले हुए)","2 बड़े चम्मच ऑलिव ऑयल","1 कप कम वसा वाला छाछ (बटरमिल्क)","2 बड़े एग व्हाइट","1 छोटा चम्मच वैनिला एक्सट्रैक्ट","1/4 कप कम या शून्य कैलोरी वाला स्वीटनर","2 कप ऑल-पर्पज़ ग्लूटेन-मुक्त बेकिंग मिक्स","3 बड़े चम्मच पिसे हुए अलसी के बीज"],
["ओवन को पहले से 350 डिग्री F पर गरम करें। 8x4 इंच के लोफ पैन पर कुकिंग स्प्रे करें।","एक बड़े कटोरे में केले, तेल, छाछ, एग व्हाइट, वैनिला और कम या शून्य कैलोरी वाला स्वीटनर मिलाएँ; अच्छी तरह मिलाएँ।","ग्लूटेन-मुक्त बेकिंग मिक्स और अलसी डालकर मिलने तक मिलाएँ। बैटर को लोफ पैन में डालें। 30–35 मिनट या बीच में डाली गई टूथपिक साफ़ बाहर आने तक बेक करें।"]))
x.append(R(6461642,"शिमला मिर्च की पट्टियाँ","शिमला मिर्च की पट्टियों की पोषण संबंधी जानकारी","1","1 कप",["1 कप शिमला मिर्च"],[]))
x.append(R(6461923,"पीकन, 1/2 औंस","पीकन की पोषण संबंधी जानकारी","1","1/2 औंस",["1/2 औंस पीकन"],[]))
x.append(R(6461989,"मूँगफली सॉस वाला टोफू, ब्रोकोलिनी और क्विनोआ","इस टोफू रेसिपी में स्वादों के स्वादिष्ट संतुलन का आनंद लें। कुरकुरा टोफू मलाईदार मूँगफली सॉस में लिपटा हुआ है और कोमल ब्रोकोलिनी और फूले हुए क्विनोआ के साथ परोसा जाता है। यह वीगन मील पैटर्न व्यंजन न सिर्फ़ पौष्टिक है, बल्कि बेहद संतोषजनक भी है।","4","1/2 कप पका हुआ क्विनोआ, 1 कप टोफू, 1/2 कप ब्रोकोलिनी",
["1 साबुत नींबू (हरा नींबू/लाइम)","1 इंच का ताज़ा अदरक का टुकड़ा (छिला हुआ और बारीक कटा हुआ)","1/4 कप पाउडर वाला पीनट बटर","2 बड़े चम्मच पानी","1 बड़ा चम्मच सोया सॉस","2 छोटे चम्मच ब्राउन शुगर","21 औंस एक्स्ट्रा फ़र्म टोफू (पानी निथारा हुआ और दबाया हुआ)","2 छोटे चम्मच कॉर्नस्टार्च","1 बड़ा चम्मच ऑलिव ऑयल","2 गुच्छे ब्रोकोलिनी","2 कप पका हुआ क्विनोआ"],
["लाइम का रस एक छोटे कटोरे में निचोड़ें।","एक कटोरे में अदरक, पीनट बटर पाउडर, पानी, सोया सॉस और ब्राउन शुगर डालें। सॉस बनाने के लिए फेंटकर मिलाएँ।","एक बड़ी कड़ाही को मध्यम आंच पर पहले से गरम करें।","कड़ाही के गरम होने के दौरान टोफू को मध्यम आकार के टुकड़ों में काटें। इसे एक मध्यम कटोरे में रखें, ऊपर से कॉर्नस्टार्च छिड़कें, फिर हल्के से मिलाकर लपेट दें।","कड़ाही गरम होने पर उसमें 2 छोटे चम्मच तेल डालें और तली पर फैलाएँ। टोफू डालें और बीच-बीच में पलटते हुए 5–7 मिनट भूरा और कुरकुरा होने तक पैन में तलें। टोफू को एक कटोरे में निकाल लें।","कड़ाही को वापस मध्यम आंच पर रखें। बचा हुआ तेल और ब्रोकोलिनी कड़ाही में डालें। बार-बार चलाते हुए 4–5 मिनट पकाएँ जब तक वह नरम पर कुरकुरी न रहे।","परोसने के लिए क्विनोआ, टोफू और ब्रोकोलिनी को कटोरों में बाँट दें। टोफू पर मूँगफली सॉस डालें।"]))
x.append(R(6462700,"बेक किए परमेसन ब्रेडेड तोरई","इटैलियन अंदाज़ के ब्रेडेड तोरई एक कुरकुरा और बच्चों को पसंद आने वाला साइड डिश हैं, जो न सिर्फ़ स्वादिष्ट है, बल्कि मधुमेह के अनुकूल और कम कार्ब वाला भी है।","6","1/2 कप",
["1 कप ब्रेड का चूरा","1/2 कप परमेसन चीज़ (कद्दूकस किया हुआ, कम सोडियम वाला)","1 छोटा चम्मच सूखा ओरेगैनो","1 छोटा चम्मच लहसुन पाउडर","1/8 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","2 बड़े अंडे (फेंटे हुए)","2 मध्यम तोरई (गोल स्लाइस में कटी हुई)","1 स्प्रे नॉनस्टिक कुकिंग स्प्रे (ऑलिव ऑयल)"],
["ओवन को पहले से 425 डिग्री F पर गरम करें।","एक कटोरे में ब्रेड का चूरा, कद्दूकस किया परमेसन चीज़, सूखा ओरेगैनो, लहसुन पाउडर, नमक और काली मिर्च मिलाएँ।","तोरई के हर गोल स्लाइस को फेंटे हुए अंडे में डुबोएँ, ध्यान रखें कि वे अच्छी तरह लिपट जाएँ।","अंडे में डूबे हर तोरई स्लाइस पर ब्रेड के चूरे का मिश्रण लपेटें और चूरे को तोरई पर दबाएँ ताकि वह चिपक जाए।","ब्रेड के चूरे में लिपटे तोरई के स्लाइस को ऑलिव ऑयल कुकिंग स्प्रे लगी बेकिंग शीट पर रखें।","ब्रेड के चूरे में लिपटे तोरई स्लाइस के ऊपरी हिस्से पर ऑलिव ऑयल कुकिंग स्प्रे हल्के से करें।","पहले से गरम ओवन में 20 मिनट या तोरई के नरम होने और परत के सुनहरी भूरी होने तक बेक करें।","तोरई को ओवन से निकालें और सर्विंग प्लेटर में रख दें।"]))
x.append(R(6464029,"चिकन सटे सलाद","यह कम वसा वाला चिकन सटे सलाद दक्षिण-पूर्व एशिया के क्लासिक व्यंजन का हल्का रूप है। कम चर्बी वाले चिकन ब्रेस्ट और पाउडर पीनट बटर से बनी मलाईदार सटे-शैली की ड्रेसिंग के साथ इसे वसा कम करके मधुमेह के अनुकूल बनाया गया है। रोमेन, खीरे और शैलट्स के ताज़ा, कुरकुरे सलाद पर परोसा गया यह तीखा, संतोषजनक और संतुलित है, जो ब्लड ग्लूकोज (रक्त शर्करा) को नियंत्रित करने में मदद करता है।","4","2 कप सलाद और 4 औंस चिकन",
["1 बड़ा चम्मच कम सोडियम वाली सोया सॉस","1 छोटा चम्मच मध्यम तीखा करी पाउडर","1/4 छोटा चम्मच पिसा जीरा","1 कली लहसुन (बारीक कद्दूकस किया हुआ)","1 पाउंड बिना हड्डी और बिना त्वचा के चिकन ब्रेस्ट (पतले फ़िलेट में कटे हुए)","1/4 कप पाउडर वाला पीनट बटर (जैसे PB2)","2 बड़े चम्मच गुनगुना पानी (मनचाही गाढ़ापन के अनुसार घटाएँ-बढ़ाएँ)","1 बड़ा चम्मच स्वीट चिली सॉस","1 बड़ा चम्मच नींबू का रस (लाइम)","2 सिर रोमेन हार्ट्स (कटे हुए)","1/2 साबुत खीरा (लंबाई में आधा काटकर स्लाइस किया हुआ)","1 छोटा शैलट (पतला कटा हुआ)","1/4 कप ताज़ा धनिया (कटा हुआ [वैकल्पिक])","1/2 कप अनार के दाने"],
["एक कटोरे में सोया सॉस, करी पाउडर, जीरा और लहसुन मिलाएँ। चिकन के स्लाइस डालें और ध्यान रखें कि वे अच्छी तरह लिपट जाएँ। ढककर कम से कम 1 घंटे, बेहतर हो तो रात भर रेफ्रिजरेटर में रखें।","एक छोटे कटोरे में पाउडर पीनट बटर को गुनगुने पानी के साथ चिकना होने तक मिलाएँ। स्वीट चिली सॉस और नींबू का रस मिलाएँ।","एक नॉनस्टिक कड़ाही या ग्रिल पैन पर हल्का तेल लगाकर मध्यम आंच पर गरम करें। मैरिनेट किए हुए चिकन को हर तरफ 5–6 मिनट पूरी तरह पकने और सुनहरा भूरा होने तक पकाएँ। प्लेट में निकालें और काटने से पहले कुछ मिनट रखा रहने दें।","एक बड़े कटोरे में रोमेन लेट्यूस, खीरा, शैलट और धनिया मिलाएँ। सलाद को चार प्लेटों में बाँट दें। हर प्लेट पर चिकन रखें और ऊपर से अनार के दाने छिड़कें। परोसने से ठीक पहले सटे ड्रेसिंग डालें।"]))
x.append(R(6464139,"नींबू की खुशबू वाला झींगा (गैम्बेरी अल लिमोन)","लेखिका एमी रियोलो कहती हैं, \"इटली से सटे सभी जल निकायों, यानी एड्रियाटिक से लेकर आयोनियन, भूमध्यसागर और टिरेनियन समुद्रों तक, में झींगे की कई किस्में मिलती हैं, इसलिए झींगा हर जगह लोकप्रिय है। अगर आपने पहले कभी झींगा नहीं पकाया है, तो आप हैरान होंगे कि यह कितना आसान है। अपनी सीफ़ूड कुकिंग क्लास में मैं अक्सर छात्रों से कहती हूँ कि अगर पहले उन्हें झींगा बनाने में बुरा अनुभव हुआ है, तो इसका कारण यह है कि वे बहुत ज़्यादा करते हैं, कम नहीं। अच्छा झींगा पकाने की कुंजी है सबसे ताज़ा झींगा चुनना और उसे बस पकने तक ही पकाना, एक सेकंड भी ज़्यादा नहीं। इस रेसिपी में छोटे, सामान्य और जंबो, सभी तरह के झींगे चलते हैं, इसलिए जो सबसे ताज़ा हो उसका बेझिझक उपयोग करें।\"","4","लगभग 4 औंस झींगा",
["1 बड़ा चम्मच एक्स्ट्रा वर्जिन ऑलिव ऑयल","1 पाउंड झींगा (छिला और नस निकाला हुआ)","1/2 छोटा चम्मच कोशर नमक","1/4 छोटा चम्मच काली मिर्च (ताज़ा पिसी हुई)","1/8 छोटा चम्मच कुटी लाल मिर्च के फ्लेक्स (स्वादानुसार)","2 बड़े चम्मच नींबू का रस (1 मध्यम नींबू से)","1 बड़ा चम्मच नींबू का ज़ेस्ट (1 मध्यम नींबू से)"],
["एक बड़ी कड़ाही में मध्यम-तेज़ आंच पर ऑलिव ऑयल गरम करें।","जब ऑलिव ऑयल से खुशबू आने लगे, तो झींगा, नमक, काली मिर्च और कुटी लाल मिर्च के फ्लेक्स डालें। झींगे को एक तरफ़ से तब तक पकाएँ जब तक झींगे की पूँछ चटक गुलाबी न हो जाए, लगभग 1–2 मिनट।","झींगे को पलटें और ऊपर से नींबू का रस निचोड़ें। झींगे को तब तक पकाएँ जब तक सारा धूसर रंग चला न जाए और वे गुलाबी और अच्छी तरह पके हुए न हो जाएँ, लगभग 1–2 मिनट और। इस समय झींगे कच्चे होने की तुलना में थोड़े ज़्यादा कसकर मुड़े होने चाहिए। झींगे पैन में छनछनाते रहेंगे।","जब वे पूरी तरह पक जाएँ, तो झींगे को सर्विंग प्लेटर में रखें, नींबू के ज़ेस्ट से सजाएँ और तुरंत परोसें।"]))
x.append(R(6466152,"रिकोटा और ब्लैकबेरी जैम क्रोस्टिनी","कुछ ख़ास सा चाहिए? यह क्रोस्टिनी रेसिपी आपकी पसंदीदा स्टार्टर बन जाएगी। यह काम के बाद या स्कूल के बाद बिना झंझट के खाने वाले नाश्ते के रूप में भी दोहरा काम करती है। इसे बनाने के लिए आपको पूरे फुट भर लंबे बैगेट की ज़रूरत नहीं है; यह रेसिपी सामान्य हॉगी या सबमरीन रोल के स्लाइस के साथ भी हैरानी भरे ढंग से अच्छी बनती है, बशर्ते वह पहले से कटा हुआ न हो।","6","2 क्रोस्टिनी",
["1 साबुत होल ग्रेन हॉगी या सबमरीन रोल","3/4 कप पार्ट-स्किम रिकोटा चीज़","1/4 कप फलों के रस से मीठा किया ब्लैकबेरी जैम","3/4 कप ताज़ी या पिघलाई हुई फ्रोज़न ब्लैकबेरी","1/8 छोटा चम्मच समुद्री नमक"],
["ब्रेड चाकू से रोल के गोल सिरे काट दें। रोल को लगभग 1/2 इंच मोटे 12 स्लाइस में काटें। ब्रेड के स्लाइस को टोस्टर में सुनहरा भूरा होने तक टोस्ट करें।","हर स्लाइस पर 1 बड़ा चम्मच रिकोटा चीज़ और फिर 1 छोटा चम्मच जैम लगाएँ। ऊपर से बराबर मात्रा में ब्लैकबेरी डालें, फिर नमक छिड़कें। प्लेटर में सजाएँ और परोसें।"]))
x.append(R(6466239,"इटैलियन अंदाज़ के भुने टमाटर","इसे रोज़ के खाने का अपना नया पसंदीदा साइड डिश बनाएँ। यह बेहद तेज़, बेहद सस्ता है, और किसी भी भोजन को ख़ास बना सकता है। आप इसे ब्राउन राइस पर डाल सकते हैं, ग्रिल किए चिकन के ऊपर सजा सकते हैं, या ताज़े हरे सलाद के साथ परोस सकते हैं। साधारण से रेस्तराँ जैसे ख़ास स्वाद तक पहुँचने का कितना आसान तरीका!","4","1/4 कप",
["1 बड़ा चम्मच ऑलिव ऑयल","1 (12 औंस) डिब्बा अंगूर या चेरी टमाटर","2 कली लहसुन (पतली कटी हुई)","2 बड़े चम्मच बाल्समिक सिरका","2 छोटे चम्मच कम कैलोरी वाला चीनी का विकल्प"],
["एक बड़ी कड़ाही में तेज़ आंच पर तेल को गरम होने तक गरम करें। टमाटरों को 4 से 5 मिनट या उनके छिलके भूरे होकर फूलने तक भूनें।","लहसुन डालें और 1 मिनट पकाएँ। बाल्समिक सिरका और चीनी का विकल्प डालें और 1 से 2 मिनट या मिश्रण के गाढ़ा होने तक पकाते रहें। गरम या कमरे के तापमान पर परोसें।"]))
